import{_ as l,a0 as s,w as p,s as n,ao as u,I as o,x as r,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何讓 KDE 看起來像 GNOME | LCTT x X-CMD","titleTemplate":false,"description":"如何讓 KDE 看起來像 GNOME | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何讓 KDE 看起來像 GNOME | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何讓 KDE 看起來像 GNOME | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220222 How to make KDE look like GNOME on Linux","title":"如何讓 KDE 看起來像 GNOME","tag":"202202","desc":""},"relativePath":"202202/20220222 How to make KDE look like GNOME on Linux.md","filePath":"[post].md"}'),d={name:"202202/20220222 How to make KDE look like GNOME on Linux.md"};function b(y,t,m,h,E,k){const e=s("Link");return p(),n("div",null,[t[15]||(t[15]=u('<h1 id="如何讓-kde-看起來像-gnome" tabindex="-1">如何讓 KDE 看起來像 GNOME <a class="header-anchor" href="#如何讓-kde-看起來像-gnome" aria-label="Permalink to “如何讓 KDE 看起來像 GNOME”">​</a></h1><blockquote><p>在不放棄你的 Plasma 桌面的情況下獲得 GNOME 的感覺。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202202/28/121405fxmzdms3a4p4mspa.jpg" alt=""></p><p>GNOME 有一種極簡主義設計的傾向。它是一種美麗的桌面體驗，並且是第一個在我使用 Linux 時引起別人讚歎的自由桌面。然後（請原諒我的形而上的哲學思考），沒有複雜性就沒有極簡主義，而 KDE 以其極具定製性而聞名。我認為測試一下 KDE 的配置可能會很有趣，並嘗試在 KDE Plasma 桌面上重新實現，至少在表面上實現 GNOME 的體驗。</p><p>如果你嘗試這個，請在一個臨時用户帳户中進行。這些變化相對來説比較劇烈，撤銷它以回到你的標準 KDE 佈局可能是一個很大的工作。</p><h3 id="adwaita-主題" tabindex="-1">Adwaita 主題 <a class="header-anchor" href="#adwaita-主題" aria-label="Permalink to “Adwaita 主題”">​</a></h3><p>GNOME 的默認主題叫做 Adwaita，是為 GTK 設計的，這是 GNOME 用於窗口和部件的工具包。KDE 使用 Qt 工具包，但 Fedora-Qt 項目已經開發了一個模仿 Adwaita 的 Qt 主題。這是在 KDE 上模仿 GNOME 的第一步，也是最明顯的一步。使用你的發行版的包管理器安裝 Adwaita for Qt：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install adwaita-qt{,5}</span></span></code></pre></div><p>在基於 Debian 的發行版上，請使用 <code>apt</code> 命令而不是 <code>dnf</code>。</p><p>安裝完畢後，進入“<ruby>系統設置<rt>System Settings</rt></ruby>”，選擇“<ruby>應用風格<rt>Application Style</rt></ruby>”。選擇你喜歡的 Adwaita 主題變體：有一個淺色主題和一個深色主題，以及兩者之間的變化。點擊“<ruby>應用<rt>Apply</rt></ruby>”按鈕來更新你的主題，但先不要關閉這個控制面板。</p><h3 id="窗口裝飾" tabindex="-1">窗口裝飾 <a class="header-anchor" href="#窗口裝飾" aria-label="Permalink to “窗口裝飾”">​</a></h3><p>在“<ruby>應用風格<rt>Application Style</rt></ruby>”窗口的左側面板中選擇“<ruby>窗口裝飾<rt>Window Decorations</rt></ruby>”分類。如果有一個適合 Adwaita 的標題欄樣式，通過選擇它並點擊“<ruby>應用<rt>Apply</rt></ruby>”來激活它。如果沒有安裝額外的裝飾，點擊面板右下方的“<ruby>獲取新窗口裝飾<rt>Get new window decorations</rt></ruby>”按鈕，下載合適的東西。我使用了用户 x-varlesh-x 提供的 “Arc” 主題，但你可以四處看看，看看什麼最適合你的其他主題。</p><p>GNOME 著名的是它的窗口標題欄上只有一個按鈕，所以導航到“<ruby>標題欄按鈕<rt>Titlebar Buttons</rt></ruby>”標籤，然後通過將“<ruby>關閉<rt>Close</rt></ruby>”按鈕從標題欄圖像拖到處置區域來刪除所有按鈕。</p><p><img src="https://opensource.com/sites/default/files/kde-decoration-remove.jpg" alt="Removing buttons" title="Removing buttons"></p><p>取消選擇“<ruby>顯示標題欄按鈕提示<rt>Show titlebar button tooltips</rt></ruby>”，因為 GNOME 不傾向於在系統部件上做提示。</p><p>點擊“<ruby>應用<rt>Apply</rt></ruby>”來保存你的修改。</p><h3 id="gtk-主題" tabindex="-1">GTK 主題 <a class="header-anchor" href="#gtk-主題" aria-label="Permalink to “GTK 主題”">​</a></h3><p>在 KDE 上，使用 GTK 的應用通常會被重新主題化成與 KDE 的默認主題一致。現在你已經把你的主題從 KDE Breeze 改為 GNOME Adwaita，你必須告訴 GTK 使用 Adwaita 主題。</p><p>點擊“<ruby>應用風格<rt>Application Style</rt></ruby>”面板底部的“<ruby>配置 GNOME/GTK 應用風格<rt>Configure GNOME/GTK application style</rt></ruby>”按鈕，在下拉菜單中選擇 “Adwaita”。</p><h3 id="工作區行為" tabindex="-1">工作區行為 <a class="header-anchor" href="#工作區行為" aria-label="Permalink to “工作區行為”">​</a></h3><p>GNOME 在視覺上比 KDE 更安靜，所以在“<ruby>系統設置<rt>System Settings</rt></ruby>”中找到“<ruby>工作區行為<rt>Workspace behavior</rt></ruby>”面板，停用“<ruby>在鼠標懸停時顯示信息提示<rt>Display informational tooltips on mouse hover</rt></ruby>”和“<ruby>顯示狀態變化的視覺反饋<rt>Display visual feedback for status changes</rt></ruby>”。</p><p>你也可以把打開文件和文件夾改為需要雙擊而不是單擊（在實際中，這對我來説太不方便了）。</p><h3 id="圖標和光標" tabindex="-1">圖標和光標 <a class="header-anchor" href="#圖標和光標" aria-label="Permalink to “圖標和光標”">​</a></h3><p>你可以在“<ruby>系統設置<rt>System Settings</rt></ruby>”中把光標改為 Adwaita 主題，然後選擇一個圖標主題。我喜歡 Breeze 的圖標，但它們確實感覺像 KDE。GNOME 使用 Adwaita 圖標集，但由於它們是為 GNOME 設計的，所以缺少一些重要的 KDE 組件的圖標。你可以點擊“<ruby>圖標<rt>Icons</rt></ruby>”控制面板中的“<ruby>獲取新圖標<rt>Get New Icons</rt></ruby>”按鈕來瀏覽很多圖標集，最後我選擇了用户 alvatip 提供的 “Nordzy”。不過，有很多不錯的圖標集可用，查看它們，看看你喜歡什麼。我發現任何不屬於 Breeze 的東西都會使 KDE 看起來與我習慣的東西有足夠的不同。</p><h3 id="系統面板" tabindex="-1">系統面板 <a class="header-anchor" href="#系統面板" aria-label="Permalink to “系統面板”">​</a></h3><p>GNOME 的面板在屏幕的頂部，而 KDE 的面板默認在屏幕的底部。GNOME 的面板在默認情況下也是比較空的，所以我發現最簡單的做法是先把當前的 KDE 面板完全刪除。</p><p>右鍵點擊並選擇“<ruby>編輯面板<rt>Edit panel</rt></ruby>”。進入編輯模式後，再次右鍵點擊面板，選擇“<ruby>刪除面板<rt>Remove panel</rt></ruby>”。當它消失了，右擊桌面上的任何地方，選擇“<ruby>添加面板<rt>Add panel</rt></ruby>”並添加一個空面板。這樣就在屏幕底部添加了一個面板，所以右擊它，選擇“<ruby>編輯面板<rt>Edit panel</rt></ruby>”，然後點擊並拖動“<ruby>屏幕邊緣<rt>Screen Edge</rt></ruby>”按鈕到屏幕的頂部。</p><p>當仍處於編輯模式時，點擊“<ruby>添加部件<rt>Add widgets</rt></ruby>”按鈕，將“<ruby>應用儀表板<rt>Application dashboard</rt></ruby>”部件添加到面板的最左端。然後從“<ruby>編輯面板<rt>Edit panel</rt></ruby>”視圖中添加一個“<ruby>間隔<rt>Spacer</rt></ruby>”塊，然後是一個“<ruby>時鐘<rt>Clock</rt></ruby>”，然後是另一個“<ruby>間隔<rt>Spacer</rt></ruby>”。你可以拖動這些小部件來排列它們，所以我發現最簡單的做法是添加上應用儀表板和時鐘，然後是兩個間隔，再把它們排列起來。</p><p><img src="https://opensource.com/sites/default/files/kde-panel-edit.jpg" alt="Editing the panel" title="Editing the panel"></p><p>你可以右鍵點擊每個小組件來定製圖標和佈局。例如，我把日期從時鐘上移走了，因為它在附加了日期後看起來很擠，儘管 GNOME 確實包含了日期。</p><p>通過進入“<ruby>系統設置<rt>System Settings</rt></ruby>”，選擇一個深色的 Plasma 主題，比如 “Breeze Dark”，將面板改為黑色。</p><h3 id="gnome-plasma-桌面" tabindex="-1">GNOME Plasma 桌面 <a class="header-anchor" href="#gnome-plasma-桌面" aria-label="Permalink to “GNOME Plasma 桌面”">​</a></h3><p>通過一些快速的調整，你的桌面現在在各個方面接近於 GNOME。佈局是類似的。</p><p><img src="https://opensource.com/sites/default/files/kde-like-gnome_0.jpg" alt="GNOME layout" title="GNOME layout"></p><p>應用儀表板提供了一個 GNOME 風格的應用啓動器。</p><p><img src="https://opensource.com/sites/default/files/kde-application-dashboard_0.jpg" alt="Application dashboard" title="Application dashboard"></p><p>其他小的修改進一步有助於產生這種錯覺。例如，我簡化了 Dolphin 文件管理器，去掉了“<ruby>位置<rt>Places</rt></ruby>”面板，也去掉了工具欄上的大部分按鈕。</p><h3 id="一個不同的視角" tabindex="-1">一個不同的視角 <a class="header-anchor" href="#一個不同的視角" aria-label="Permalink to “一個不同的視角”">​</a></h3><p>這不是一個精確的匹配，比我更具鑽研精神的人可以做的更多，得到更接近正確的結果。然而，像這樣有趣的變化證明了 KDE 是多麼的靈活，擁有大量的選項意味着你可以縮減你的交互內容以適應你的偏好。一個類似 GNOME 的桌面可以給你一個新的視角來看待你與桌面的互動，即使你不會永遠保持這種佈局，它可以幫助你發現你可能沒有想到要尋找的選項。</p><hr>',40)),o("p",null,[t[1]||(t[1]=r("via: ",-1)),a(e,{href:"https://opensource.com/article/22/2/make-kde-look-like-gnome"},{default:i(()=>[...t[0]||(t[0]=[r("https://opensource.com/article/22/2/make-kde-look-like-gnome",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=r("作者：",-1)),a(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[2]||(t[2]=[r("Seth Kenlon",-1)])]),_:1}),t[7]||(t[7]=r(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[3]||(t[3]=[r("lujun9972",-1)])]),_:1}),t[8]||(t[8]=r(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:i(()=>[...t[4]||(t[4]=[r("geekpi",-1)])]),_:1}),t[9]||(t[9]=r(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[r("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=r("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[r("LCTT",-1)])]),_:1}),t[13]||(t[13]=r(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[r("Linux中國",-1)])]),_:1}),t[14]||(t[14]=r(" 榮譽推出",-1))])])}const G=l(d,[["render",b]]);export{c as __pageData,G as default};
